void pagevec_unmark_locks(struct pagevec *pvec, struct zone *zone) {
    int i, unlocked = 0;
    struct page *backup[PAGEVEC_SIZE];
    int bidx = 0;

    /* Phase 1: Isolate pages and prepare backup vector */
    for (i = 0; i < pagevec_count(pvec); i++) {
        struct page *page = pvec->pages[i];
        if (PageLocked(page)) {
            unlock_page(page);
            unlocked++;
        } else {
            backup[bidx++] = page;
        }
    }

    /* Phase 2: Unlock and manage state for pages */
    for (i = 0; i < pagevec_count(pvec); i++) {
        struct page *page = pvec->pages[i];
        if (!PageLocked(page)) {
            if (page_count(page) == 1)
                __put_page(page);
            else
                put_page(page);
        }
    }

    /* Phase 3: Process fast path putback */
    for (i = 0; i < bidx; i++) {
        struct page *page = backup[i];
        if (page_count(page) == 1)
            __put_page(page);
        else
            put_page(page);
    }

    /* Update zone state if needed */
    if (unlocked)
        zone->pages_unlocked += unlocked;
}

void pagevec_release(struct pagevec *pvec, struct zone *zone) {
    struct page *page;
    int i, nr_unlocked = 0;

    for (i = 0; i < pvec->nr_pages; i++) {
        page = pvec->pages[i];

        if (PageLocked(page)) {
            UnlockPage(page);
            nr_unlocked++;
        } else {
            pvec->pages[i] = NULL;
        }
    }

    if (nr_unlocked > 0) {
        for (i = 0; i < pvec->nr_pages; i++) {
            page = pvec->pages[i];
            if (page != NULL) {
                if (page->count == 1) {
                    page->count = 0;
                } else {
                    page->count--;
                }
            }
        }
    }

    for (i = 0; i < pvec->nr_pages; i++) {
        page = pvec->pages[i];
        if (page != NULL) {
            zone->free_pages += 1;
            page->zone = zone;
        }
    }

    pvec->nr_pages = 0;
}

void pagevec_unlock(struct pagevec *pvec, struct zone *zone) {
    struct page *page;
    int i;
    struct pagevec backup_pvec;
    int backup_count = 0;

    /* Phase 1: Isolate pages and prepare backup */
    pagevec_init(&backup_pvec);
    for (i = 0; i < pagevec_count(pvec); i++) {
        page = pvec->pages[i];
        if (PageLocked(page)) {
            continue;
        }
        if (backup_count < PAGEVEC_SIZE) {
            backup_pvec.pages[backup_count++] = page;
        }
    }

    /* Adjust the count of unlocked pages */
    for (i = 0; i < backup_count; i++) {
        page = backup_pvec.pages[i];
        unlock_page(page);
    }

    /* Phase 2: Unlock pages and manage state */
    for (i = 0; i < pagevec_count(pvec); i++) {
        page = pvec->pages[i];
        if (PageLocked(page)) {
            unlock_page(page);
            atomic_dec(&zone->pages_locked);
        }
    }

    /* Phase 3: Process fast path putback */
    for (i = 0; i < backup_count; i++) {
        page = backup_pvec.pages[i];
        __free_page(page);
    }

    pagevec_reinit(pvec);
}

