void release_pages_and_unlock(struct pagevec *pvec, struct zone *zone) {
    struct page *page;
    int i;
    int unlock_count = 0;
    struct page *backup[PAGEVEC_SIZE];
    int backup_index = 0;

    /* Phase 1: Isolate pages that are locked and prepare a backup vector */
    for (i = 0; i < pagevec_count(pvec); i++) {
        page = pvec->pages[i];
        if (PageLocked(page)) {
            unlock_count++;
        } else {
            backup[backup_index++] = page;
        }
    }

    /* Phase 2: Unlock pages and manage their state */
    for (i = 0; i < pagevec_count(pvec); i++) {
        page = pvec->pages[i];
        if (PageLocked(page)) {
            unlock_page(page);
            zone->pages_locked--;
        }
    }

    /* Phase 3: Process fast path putback for non-locked pages */
    for (i = 0; i < backup_index; i++) {
        page = backup[i];
        __page_cache_release(page);
        zone->free_pages++;
    }

    pagevec_reinit(pvec);
}
